svg.script:
//    (necesario en SVG puro para evitar errores de parseo XML)

// Obtener referencia al elemento texto por su ID
var texto = document.getElementById("miTexto");
// Obtener referencia al elemento círculo por su ID
var circulo = document.getElementById("miCirculo");

// Agregar evento click al texto
texto.addEventListener("click", function() {
  // Cambiar el contenido del texto a "¡Click!"
  texto.textContent = "¡Click!";
  // Cambiar el color del texto a rojo (fill en SVG)
  texto.setAttribute("fill", "red");
});

// Agregar evento click al círculo
circulo.addEventListener("click", function() {
  // Cambiar el color de relleno del círculo a verde
  circulo.setAttribute("fill", "green");
  // Aumentar el radio del círculo a 45
  circulo.setAttribute("r", "45");
});

//
